CREATE DATABASE IF NOT EXISTS parkease CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE parkease;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(25),vehicle_number VARCHAR(30) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE slots (id INT AUTO_INCREMENT PRIMARY KEY,slot_number VARCHAR(20) NOT NULL UNIQUE,location VARCHAR(100) NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,status ENUM('available','reserved','occupied','maintenance') NOT NULL DEFAULT 'available');
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,slot_id INT NOT NULL,booking_code VARCHAR(30) NOT NULL UNIQUE,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,actual_entry DATETIME NULL,actual_exit DATETIME NULL,parking_amount DECIMAL(10,2) NOT NULL,fine_amount DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('pending_payment','paid','entered','completed','cancelled') NOT NULL DEFAULT 'pending_payment',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(slot_id) REFERENCES slots(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,method VARCHAR(50) NOT NULL,status ENUM('paid','failed','refunded') NOT NULL DEFAULT 'paid',paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id));
